// Covers Electron helper supervision through a private readiness pipe and bounded shutdown.

import { describe, expect, it } from "vitest";

import { startManagedHelper, type ManagedHelper } from "./helperSupervisor.js";

const READY_NONCE = "REDACTED";

function fakeHelperScript(): string {
  return [
    "const fs = require('node:fs');",
    `fs.writeSync(3, JSON.stringify({type:'ready',protocolVersion:1,port:43123,instanceNonce:'${READY_NONCE}'}) + '\\n');`,
    "process.on('SIGTERM', () => process.exit(0));",
    "setInterval(() => {}, 1000);",
  ].join("");
}

describe("startManagedHelper", () => {
  it("reads readiness from fd 3 and stops the live child cleanly", async () => {
    let helper: ManagedHelper | undefined;
    try {
      helper = await startManagedHelper({
        command: process.execPath,
        arguments: ["--eval", fakeHelperScript()],
        environment: {},
        readinessTimeoutMs: 2_000,
        shutdownTimeoutMs: 2_000,
      });

      expect(helper.ready).toEqual({ port: 43123, instanceNonce: READY_NONCE });
      expect(helper.processId).toBeGreaterThan(0);
      expect(helper.running).toBe(true);
    } finally {
      await helper?.stop();
    }

    expect(helper?.running).toBe(false);
  });
});

export interface ManagedHelper {
  readonly ready: { port: number; instanceNonce: string };
  readonly processId: number;
  readonly running: boolean;
  stop(): Promise<void>;
}

export interface StartManagedHelperOptions {
  command: string;
  arguments: string[];
  environment: Record<string, string>;
  readinessTimeoutMs: number;
  shutdownTimeoutMs: number;
}

export async function startManagedHelper(
  _options: StartManagedHelperOptions,
): Promise<ManagedHelper> {
  throw new Error("helper supervisor is not implemented");
}

import { spawn, type ChildProcess } from "node:child_process";
import path from "node:path";
import { Readable } from "node:stream";

import { parseHelperReadyLine, type HelperReadyMessage } from "./helperProtocol.js";

const READY_MESSAGE_BYTES_MAX = 4_096;

export interface ManagedHelper {
  readonly ready: HelperReadyMessage;
  readonly processId: number;
  readonly running: boolean;
  stop(): Promise<void>;
}

export interface StartManagedHelperOptions {
  command: string;
  arguments: string[];
  environment: Record<string, string>;
  readinessTimeoutMs: number;
  shutdownTimeoutMs: number;
}

function isRunning(child: ChildProcess): boolean {
  return child.exitCode === null && child.signalCode === null;
}

function validateOptions(options: StartManagedHelperOptions): void {
  if (options === null || typeof options !== "object") {
    throw new TypeError("helper options must be an object");
  }
  if (typeof options.command !== "string" || !path.isAbsolute(options.command)) {
    throw new TypeError("helper command must be an absolute path");
  }
  if (!Array.isArray(options.arguments) || options.arguments.some((value) => typeof value !== "string")) {
    throw new TypeError("helper arguments must be strings");
  }
  if (options.environment === null || typeof options.environment !== "object") {
    throw new TypeError("helper environment must be an object");
  }
  if (!Number.isInteger(options.readinessTimeoutMs) || options.readinessTimeoutMs < 1) {
    throw new TypeError("readinessTimeoutMs must be a positive integer");
  }
  if (!Number.isInteger(options.shutdownTimeoutMs) || options.shutdownTimeoutMs < 1) {
    throw new TypeError("shutdownTimeoutMs must be a positive integer");
  }
}

function waitForExit(child: ChildProcess, timeoutMs: number): Promise<boolean> {
  if (!isRunning(child)) {
    return Promise.resolve(true);
  }

  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => finish(false), timeoutMs);
    const onExit = () => finish(true);
    const onError = () => fail(new Error("helper process emitted an error while stopping"));

    function cleanup(): void {
      clearTimeout(timeout);
      child.off("exit", onExit);
      child.off("error", onError);
    }
    function finish(exited: boolean): void {
      cleanup();
      resolve(exited);
    }
    function fail(error: Error): void {
      cleanup();
      reject(error);
    }

    child.once("exit", onExit);
    child.once("error", onError);
  });
}

async function stopChild(child: ChildProcess, timeoutMs: number): Promise<void> {
  if (!isRunning(child)) {
    return;
  }

  child.kill("SIGTERM");
  if (await waitForExit(child, timeoutMs)) {
    return;
  }
  child.kill("SIGKILL");
  if (!(await waitForExit(child, timeoutMs))) {
    throw new Error("helper process did not stop after SIGKILL");
  }
}

function readReadyMessage(
  child: ChildProcess,
  readyPipe: Readable,
  timeoutMs: number,
): Promise<HelperReadyMessage> {
  return new Promise((resolve, reject) => {
    let buffered = Buffer.alloc(0);
    const timeout = setTimeout(
      () => fail(new Error("helper readiness timed out")),
      timeoutMs,
    );
    const onChildError = () => fail(new Error("helper process failed before readiness"));
    const onChildExit = () => fail(new Error("helper process exited before readiness"));
    const onPipeError = () => fail(new Error("helper readiness pipe failed"));
    const onData = (chunk: Buffer | string) => {
      const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      buffered = Buffer.concat([buffered, bytes]);
      if (buffered.length > READY_MESSAGE_BYTES_MAX) {
        fail(new Error("helper readiness exceeded the byte limit"));
        return;
      }
      const newlineIndex = buffered.indexOf(0x0a);
      if (newlineIndex < 0) {
        return;
      }
      try {
        finish(parseHelperReadyLine(buffered.subarray(0, newlineIndex).toString("utf8")));
      } catch (error) {
        fail(error instanceof Error ? error : new Error("helper readiness was invalid"));
      }
    };

    function cleanup(): void {
      clearTimeout(timeout);
      child.off("error", onChildError);
      child.off("exit", onChildExit);
      readyPipe.off("error", onPipeError);
      readyPipe.off("data", onData);
    }
    function finish(message: HelperReadyMessage): void {
      cleanup();
      resolve(message);
    }
    function fail(error: Error): void {
      cleanup();
      reject(error);
    }

    child.once("error", onChildError);
    child.once("exit", onChildExit);
    readyPipe.once("error", onPipeError);
    readyPipe.on("data", onData);
  });
}

class ManagedHelperProcess implements ManagedHelper {
  readonly ready: HelperReadyMessage;
  readonly processId: number;
  readonly #child: ChildProcess;
  readonly #shutdownTimeoutMs: number;
  #stopPromise: Promise<void> | undefined;

  constructor(child: ChildProcess, ready: HelperReadyMessage, shutdownTimeoutMs: number) {
    if (child.pid === undefined || child.pid < 1) {
      throw new Error("helper process did not receive a process id");
    }
    if (!Number.isInteger(shutdownTimeoutMs) || shutdownTimeoutMs < 1) {
      throw new TypeError("shutdownTimeoutMs must be a positive integer");
    }
    this.#child = child;
    this.ready = ready;
    this.processId = child.pid;
    this.#shutdownTimeoutMs = shutdownTimeoutMs;
  }

  get running(): boolean {
    return isRunning(this.#child);
  }

  stop(): Promise<void> {
    this.#stopPromise ??= stopChild(this.#child, this.#shutdownTimeoutMs);
    return this.#stopPromise;
  }
}

export async function startManagedHelper(
  options: StartManagedHelperOptions,
): Promise<ManagedHelper> {
  validateOptions(options);
  const child = spawn(options.command, options.arguments, {
    detached: false,
    env: options.environment,
    stdio: ["ignore", "ignore", "ignore", "pipe"],
    windowsHide: true,
  });
  const readyPipe = child.stdio[3];
  if (!(readyPipe instanceof Readable)) {
    await stopChild(child, options.shutdownTimeoutMs);
    throw new Error("helper readiness pipe was not created");
  }

  try {
    const ready = await readReadyMessage(child, readyPipe, options.readinessTimeoutMs);
    if (!isRunning(child)) {
      throw new Error("helper process exited after readiness");
    }
    return new ManagedHelperProcess(child, ready, options.shutdownTimeoutMs);
  } catch (error) {
    await stopChild(child, options.shutdownTimeoutMs);
    throw error;
  }
}

import { spawn, type ChildProcess } from "node:child_process";
import { Readable } from "node:stream";

import { parseHelperReadyLine, type HelperReadyMessage } from "./helperProtocol.js";

export interface ManagedHelper {
  readonly ready: HelperReadyMessage;
  readonly processId: number;
  readonly running: boolean;
  stop(): Promise<void>;
}

export interface StartManagedHelperOptions {
  command: string;
  arguments: string[];
  environment: Record<string, string>;
  readinessTimeoutMs: number;
  shutdownTimeoutMs: number;
}

function childIsRunning(child: ChildProcess): boolean {
  return child.exitCode === null && child.signalCode === null;
}

function waitForReadiness(
  child: ChildProcess,
  readyPipe: Readable,
  timeoutMs: number,
): Promise<HelperReadyMessage> {
  return new Promise((resolve, reject) => {
    let buffered = "";
    const timeout = setTimeout(
      () => finish(new Error("helper readiness timed out")),
      timeoutMs,
    );
    const onExit = () => finish(new Error("helper exited before readiness"));
    const onError = () => finish(new Error("helper failed before readiness"));
    const onData = (chunk: Buffer | string) => {
      buffered += chunk.toString();
      const newlineIndex = buffered.indexOf("\n");
      if (newlineIndex < 0) {
        return;
      }
      try {
        finish(undefined, parseHelperReadyLine(buffered.slice(0, newlineIndex)));
      } catch (error) {
        finish(error instanceof Error ? error : new Error("helper readiness was invalid"));
      }
    };

    function cleanup(): void {
      clearTimeout(timeout);
      child.off("exit", onExit);
      child.off("error", onError);
      readyPipe.off("data", onData);
    }
    function finish(error?: Error, ready?: HelperReadyMessage): void {
      cleanup();
      if (error !== undefined) {
        reject(error);
        return;
      }
      if (ready === undefined) {
        reject(new Error("helper readiness was missing"));
        return;
      }
      resolve(ready);
    }

    child.once("exit", onExit);
    child.once("error", onError);
    readyPipe.on("data", onData);
  });
}

function waitForExit(child: ChildProcess, timeoutMs: number): Promise<void> {
  if (!childIsRunning(child)) {
    return Promise.resolve();
  }
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      cleanup();
      reject(new Error("helper shutdown timed out"));
    }, timeoutMs);
    const onExit = () => {
      cleanup();
      resolve();
    };
    function cleanup(): void {
      clearTimeout(timeout);
      child.off("exit", onExit);
    }
    child.once("exit", onExit);
  });
}

class ManagedHelperProcess implements ManagedHelper {
  readonly ready: HelperReadyMessage;
  readonly processId: number;
  readonly #child: ChildProcess;
  readonly #shutdownTimeoutMs: number;

  constructor(child: ChildProcess, ready: HelperReadyMessage, shutdownTimeoutMs: number) {
    if (child.pid === undefined || child.pid < 1) {
      throw new Error("helper process id was unavailable");
    }
    if (!Number.isInteger(shutdownTimeoutMs) || shutdownTimeoutMs < 1) {
      throw new TypeError("shutdownTimeoutMs must be a positive integer");
    }
    this.#child = child;
    this.ready = ready;
    this.processId = child.pid;
    this.#shutdownTimeoutMs = shutdownTimeoutMs;
  }

  get running(): boolean {
    return childIsRunning(this.#child);
  }

  async stop(): Promise<void> {
    if (!this.running) {
      return;
    }
    this.#child.kill("SIGTERM");
    await waitForExit(this.#child, this.#shutdownTimeoutMs);
  }
}

export async function startManagedHelper(
  options: StartManagedHelperOptions,
): Promise<ManagedHelper> {
  if (typeof options.command !== "string" || options.command.length === 0) {
    throw new TypeError("helper command must be a non-empty string");
  }
  if (!Number.isInteger(options.readinessTimeoutMs) || options.readinessTimeoutMs < 1) {
    throw new TypeError("readinessTimeoutMs must be a positive integer");
  }

  const child = spawn(options.command, options.arguments, {
    env: options.environment,
    stdio: ["ignore", "ignore", "ignore", "pipe"],
  });
  const readyPipe = child.stdio[3];
  if (!(readyPipe instanceof Readable)) {
    child.kill("SIGTERM");
    throw new Error("helper readiness pipe was unavailable");
  }
  const ready = await waitForReadiness(child, readyPipe, options.readinessTimeoutMs);
  return new ManagedHelperProcess(child, ready, options.shutdownTimeoutMs);
}

import { spawn } from "node:child_process";
import { once } from "node:events";
import { createInterface } from "node:readline";
import { Readable } from "node:stream";

import { parseHelperReadyLine, type HelperReadyMessage } from "./helperProtocol.js";

export interface ManagedHelper {
  readonly ready: HelperReadyMessage;
  readonly processId: number;
  readonly running: boolean;
  stop(): Promise<void>;
}

export interface StartManagedHelperOptions {
  command: string;
  arguments: string[];
  environment: Record<string, string>;
  readinessTimeoutMs: number;
  shutdownTimeoutMs: number;
}

export async function startManagedHelper(
  options: StartManagedHelperOptions,
): Promise<ManagedHelper> {
  const child = spawn(options.command, options.arguments, {
    env: options.environment,
    stdio: ["ignore", "ignore", "ignore", "pipe"],
  });
  const readyPipe = child.stdio[3];
  if (!(readyPipe instanceof Readable)) {
    child.kill("SIGTERM");
    throw new Error("helper readiness pipe was unavailable");
  }

  const lines = createInterface({ input: readyPipe, crlfDelay: Infinity });
  const firstLine = await lines[Symbol.asyncIterator]().next();
  lines.close();
  if (firstLine.done || typeof firstLine.value !== "string") {
    child.kill("SIGTERM");
    throw new Error("helper closed readiness pipe without a message");
  }
  const ready = parseHelperReadyLine(firstLine.value);
  if (child.pid === undefined || child.pid < 1) {
    child.kill("SIGTERM");
    throw new Error("helper process id was unavailable");
  }

  let stopPromise: Promise<void> | undefined;
  return {
    ready,
    processId: child.pid,
    get running(): boolean {
      return child.exitCode === null && child.signalCode === null;
    },
    stop(): Promise<void> {
      stopPromise ??= (async () => {
        if (child.exitCode !== null || child.signalCode !== null) {
          return;
        }
        const exitPromise = once(child, "exit");
        child.kill("SIGTERM");
        await exitPromise;
      })();
      return stopPromise;
    },
  };
}

