@router.get("/desktop/authorize/{request_id}")
async def authorize_desktop_request(
    request_id: str,
    request: Request,
) -> RedirectResponse:
    """Return a PKCE authorization code to one validated desktop callback."""
    user_id = _current_user_id(request)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Sign in before authorizing the desktop app")
    if len(request_id) < 32 or len(request_id) > 128:
        raise HTTPException(status_code=404, detail="Desktop authorization request not found")

    request_id_hash = hashlib.sha256(request_id.encode("utf-8")).hexdigest()
    with get_control_db() as database:
        row = database.execute(
            """
            SELECT redirect_uri, state, expires_at
            FROM desktop_authorization_requests
            WHERE request_id_hash = ?
            """,
            (request_id_hash,),
        ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="Desktop authorization request not found")
    if int(row["expires_at"]) <= int(time.time()):
        raise HTTPException(status_code=410, detail="Desktop authorization request expired")

    authorization_code = secrets.token_urlsafe(32)
    callback_query = urlencode({"code": authorization_code, "state": row["state"]})
    return RedirectResponse(url=f"{row['redirect_uri']}?{callback_query}", status_code=307)


