import {
  generateKeyPairSync,
  sign,
  type KeyObject,
} from "node:crypto";

import { describe, expect, it } from "vitest";

import {
  assertSigningKeyContinuity,
  verifyAccountLease,
} from "./accountLease.js";

interface LeaseFixture {
  readonly publicKey: string;
  readonly token: string;
}

function encodeJson(value: object): string {
  return Buffer.from(JSON.stringify(value), "utf8").toString("base64url");
}

function rawPublicKey(publicKey: KeyObject): string {
  const spki = publicKey.export({ format: "der", type: "spki" });
  return spki.subarray(spki.length - 32).toString("base64url");
}

function createLease(
  issuedAt: number,
  expiresAt: number,
  overrides: Record<string, unknown> = {},
): LeaseFixture {
  const { privateKey, publicKey } = generateKeyPairSync("ed25519");
  const header = encodeJson({ alg: "EdDSA", typ: "YINSHI-LEASE", v: 1 });
  const payload = encodeJson({
    aud: "yinshi-desktop",
    sub: "user-id",
    device_id: "device-id",
    iat: issuedAt,
    exp: expiresAt,
    v: 1,
    ...overrides,
  });
  const signingInput = `${header}.${payload}`;
  const signature = sign(null, Buffer.from(signingInput, "ascii"), privateKey);
  return {
    publicKey: rawPublicKey(publicKey),
    token: `${signingInput}.${signature.toString("base64url")}`,
  };
}

describe("verifyAccountLease", () => {
  it("accepts only a current 30-day lease signed by the pinned key", () => {
    const issuedAt = 1_700_000_000;
    const lease = createLease(issuedAt, issuedAt + 30 * 24 * 60 * 60);

    const claims = verifyAccountLease({
      token: lease.token,
      signingPublicKey: lease.publicKey,
      currentTimeSeconds: issuedAt + 1,
    });

    expect(claims).toEqual({
      userId: "user-id",
      deviceId: "device-id",
      issuedAt,
      expiresAt: issuedAt + 30 * 24 * 60 * 60,
    });

    expect(() =>
      verifyAccountLease({
        token: lease.token,
        signingPublicKey: lease.publicKey,
        currentTimeSeconds: issuedAt + 30 * 24 * 60 * 60,
      }),
    ).toThrow("account lease is invalid");

    const overlongLease = createLease(issuedAt, issuedAt + 30 * 24 * 60 * 60 + 1);
    expect(() =>
      verifyAccountLease({
        token: overlongLease.token,
        signingPublicKey: overlongLease.publicKey,
        currentTimeSeconds: issuedAt + 1,
      }),
    ).toThrow("account lease is invalid");
  });

  it("rejects tampering, wrong token types, and signing-key changes", () => {
    const lease = createLease(100, 200);
    const otherLease = createLease(100, 200);
    const replacementTail = lease.token.endsWith("A") ? "B" : "A";
    const tamperedToken = `${lease.token.slice(0, -1)}${replacementTail}`;
    const accessToken = createLease(100, 200, { token_use: "access" });
    const [header, payload, signature] = accessToken.token.split(".");
    const accessHeader = encodeJson({ alg: "EdDSA", typ: "YINSHI-ACCESS", v: 1 });

    expect(() =>
      verifyAccountLease({
        token: tamperedToken,
        signingPublicKey: lease.publicKey,
        currentTimeSeconds: 150,
      }),
    ).toThrow("account lease is invalid");
    expect(() =>
      verifyAccountLease({
        token: `${accessHeader}.${payload}.${signature}`,
        signingPublicKey: accessToken.publicKey,
        currentTimeSeconds: 150,
      }),
    ).toThrow("account lease is invalid");
    expect(() => assertSigningKeyContinuity(lease.publicKey, otherLease.publicKey)).toThrow(
      "desktop signing key changed",
    );
    expect(assertSigningKeyContinuity(lease.publicKey, lease.publicKey)).toBe(lease.publicKey);
    expect(header).not.toBe(accessHeader);
  });
});

