const { notarize } = require("@electron/notarize");

module.exports = async function notarizeMacApplication(context) {
  if (process.env.YINSHI_RELEASE_BUILD !== "1" || context.electronPlatformName !== "darwin") {
    return;
  }
  const appleApiKey = process.env.APPLE_API_KEY;
  const appleApiKeyId = process.env.APPLE_API_KEY_ID;
  const appleApiIssuer = process.env.APPLE_API_ISSUER;
  if (!appleApiKey || !appleApiKeyId || !appleApiIssuer) {
    throw new Error("Release notarization credentials are required");
  }
  const applicationPath = `${context.appOutDir}/${context.packager.appInfo.productFilename}.app`;
  await notarize({
    appBundleId: context.packager.appInfo.id,
    appPath: applicationPath,
    appleApiKey,
    appleApiKeyId,
    appleApiIssuer,
  });
};

import { expect, it } from "vitest";

import { startAutomaticUpdates, type UpdateAdapter } from "./automaticUpdates.js";

it("enforces stable signed update policy only for packaged applications", async () => {
  const listeners = new Map<string, () => void>();
  const scheduled: Array<{ delayMs: number; callback: () => void; cancelled: boolean }> = [];
  let checks = 0;
  const updater: UpdateAdapter = {
    autoDownload: false,
    autoInstallOnAppQuit: false,
    allowDowngrade: true,
    allowPrerelease: true,
    disableWebInstaller: false,
    logger: null,
    on: (event, listener) => {
      listeners.set(event, listener);
    },
    checkForUpdates: async () => {
      checks += 1;
    },
  };
  let downloaded = false;

  const updates = startAutomaticUpdates({
    isPackaged: true,
    updater,
    schedule: (delayMs, callback) => {
      const task = { delayMs, callback, cancelled: false };
      scheduled.push(task);
      return { cancel: () => (task.cancelled = true) };
    },
    onDownloaded: () => {
      downloaded = true;
    },
  });

  expect(updater.autoDownload).toBe(true);
  expect(updater.autoInstallOnAppQuit).toBe(true);
  expect(updater.allowDowngrade).toBe(false);
  expect(updater.allowPrerelease).toBe(false);
  expect(updater.disableWebInstaller).toBe(true);
  expect(scheduled[0]?.delayMs).toBe(30_000);
  scheduled[0]?.callback();
  await Promise.resolve();
  expect(checks).toBe(1);
  expect(scheduled[1]?.delayMs).toBe(6 * 60 * 60 * 1_000);
  listeners.get("update-downloaded")?.();
  expect(downloaded).toBe(true);
  updates.stop();
  expect(scheduled.at(-1)?.cancelled).toBe(true);
});

export interface UpdateAdapter {
  autoDownload: boolean;
  autoInstallOnAppQuit: boolean;
  allowDowngrade: boolean;
  allowPrerelease: boolean;
  disableWebInstaller: boolean;
  logger: unknown;
  on(event: "update-downloaded" | "error", listener: () => void): void;
  checkForUpdates(): Promise<unknown>;
}

export interface ScheduledUpdateTask {
  cancel(): void;
}

export interface AutomaticUpdateOptions {
  readonly isPackaged: boolean;
  readonly updater: UpdateAdapter;
  readonly schedule: (delayMs: number, callback: () => void) => ScheduledUpdateTask;
  readonly onDownloaded: () => void;
}

export interface AutomaticUpdateController {
  stop(): void;
}

export function startAutomaticUpdates(
  _options: AutomaticUpdateOptions,
): AutomaticUpdateController {
  throw new Error("automatic updates are not implemented");
}

const UPDATE_CHECK_DELAY_INITIAL_MS = 30_000;
const UPDATE_CHECK_INTERVAL_MS = 6 * 60 * 60 * 1_000;

export interface UpdateAdapter {
  autoDownload: boolean;
  autoInstallOnAppQuit: boolean;
  allowDowngrade: boolean;
  allowPrerelease: boolean;
  disableWebInstaller: boolean;
  logger: unknown;
  on(event: "update-downloaded" | "error", listener: () => void): void;
  checkForUpdates(): Promise<unknown>;
}

export interface ScheduledUpdateTask {
  cancel(): void;
}

export interface AutomaticUpdateOptions {
  readonly isPackaged: boolean;
  readonly updater: UpdateAdapter;
  readonly schedule: (delayMs: number, callback: () => void) => ScheduledUpdateTask;
  readonly onDownloaded: () => void;
}

export interface AutomaticUpdateController {
  stop(): void;
}

const sanitizedLogger = Object.freeze({
  debug: (): void => undefined,
  error: (): void => undefined,
  info: (): void => undefined,
  warn: (): void => undefined,
});

export function startAutomaticUpdates(
  options: AutomaticUpdateOptions,
): AutomaticUpdateController {
  if (!options.isPackaged) {
    return Object.freeze({ stop: (): void => undefined });
  }
  if (typeof options.schedule !== "function" || typeof options.onDownloaded !== "function") {
    throw new TypeError("automatic update callbacks are invalid");
  }

  options.updater.autoDownload = true;
  options.updater.autoInstallOnAppQuit = true;
  options.updater.allowDowngrade = false;
  options.updater.allowPrerelease = false;
  options.updater.disableWebInstaller = true;
  options.updater.logger = sanitizedLogger;

  let stopped = false;
  let scheduledTask: ScheduledUpdateTask | undefined;
  const scheduleCheck = (delayMs: number): void => {
    if (stopped) {
      return;
    }
    scheduledTask = options.schedule(delayMs, () => {
      void (async () => {
        if (stopped) {
          return;
        }
        try {
          await options.updater.checkForUpdates();
        } catch {
          // Update errors are intentionally sanitized and retried on the fixed interval.
        }
        scheduleCheck(UPDATE_CHECK_INTERVAL_MS);
      })();
    });
  };
  options.updater.on("update-downloaded", () => {
    if (!stopped) {
      options.onDownloaded();
    }
  });
  options.updater.on("error", () => undefined);
  scheduleCheck(UPDATE_CHECK_DELAY_INITIAL_MS);

  return Object.freeze({
    stop(): void {
      if (stopped) {
        return;
      }
      stopped = true;
      scheduledTask?.cancel();
      scheduledTask = undefined;
    },
  });
}

