import { chacha20poly1305 } from "@noble/ciphers/chacha.js";
import { x25519 } from "@noble/curves/ed25519.js";
import { hmac } from "@noble/hashes/hmac.js";
import { sha256 } from "@noble/hashes/sha2.js";

const NOISE_PROTOCOL_NAME = "Noise_IK_25519_ChaChaPoly_SHA256";
const HASH_LENGTH = 32;
const KEY_LENGTH = 32;
const X25519_KEY_LENGTH = 32;
const CHACHA_TAG_LENGTH = 16;
const NONCE_MAX = (1n << 64n) - 2n;
const emptyBytes = new Uint8Array();

export interface NoiseIkInitiatorOptions {
  readonly staticPrivateKey: Uint8Array;
  readonly ephemeralPrivateKey: Uint8Array;
  readonly responderStaticPublicKey: Uint8Array;
  readonly prologue: Uint8Array;
}

export interface NoiseIkInitiator {
  readonly handshakeHash: Uint8Array;
  writeHandshakeMessage(payload: Uint8Array): Uint8Array;
  readHandshakeMessage(message: Uint8Array): Uint8Array;
  encrypt(plaintext: Uint8Array): Uint8Array;
  decrypt(ciphertext: Uint8Array): Uint8Array;
}

function copyExact(value: Uint8Array, length: number, name: string): Uint8Array {
  if (!(value instanceof Uint8Array) || value.length !== length) {
    throw new TypeError(`${name} must contain exactly ${length} bytes`);
  }
  return Uint8Array.from(value);
}

function copyBytes(value: Uint8Array, name: string): Uint8Array {
  if (!(value instanceof Uint8Array)) {
    throw new TypeError(`${name} must be Uint8Array`);
  }
  return Uint8Array.from(value);
}

function concat(...values: readonly Uint8Array[]): Uint8Array {
  const result = new Uint8Array(values.reduce((total, value) => total + value.length, 0));
  let offset = 0;
  for (const value of values) {
    result.set(value, offset);
    offset += value.length;
  }
  return result;
}

function hkdf2(chainingKey: Uint8Array, inputKeyMaterial: Uint8Array): [Uint8Array, Uint8Array] {
  const temporaryKey = hmac(sha256, chainingKey, inputKeyMaterial);
  const output1 = hmac(sha256, temporaryKey, Uint8Array.of(1));
  const output2 = hmac(sha256, temporaryKey, concat(output1, Uint8Array.of(2)));
  return [output1, output2];
}

function noiseNonce(counter: bigint): Uint8Array {
  if (counter < 0n || counter > NONCE_MAX) {
    throw new Error("Noise cipher nonce is exhausted");
  }
  const nonce = new Uint8Array(12);
  let remaining = counter;
  for (let index = 4; index < nonce.length; index += 1) {
    nonce[index] = Number(remaining & 0xffn);
    remaining >>= 8n;
  }
  return nonce;
}

class CipherState {
  readonly #key: Uint8Array;
  #nonce = 0n;

  constructor(key: Uint8Array) {
    this.#key = copyExact(key, KEY_LENGTH, "Noise cipher key");
  }

  encryptWithAd(additionalData: Uint8Array, plaintext: Uint8Array): Uint8Array {
    const cipher = chacha20poly1305(this.#key, noiseNonce(this.#nonce), additionalData);
    const ciphertext = cipher.encrypt(plaintext);
    this.#nonce += 1n;
    return ciphertext;
  }

  decryptWithAd(additionalData: Uint8Array, ciphertext: Uint8Array): Uint8Array {
    if (ciphertext.length < CHACHA_TAG_LENGTH) {
      throw new Error("Noise ciphertext is truncated");
    }
    const cipher = chacha20poly1305(this.#key, noiseNonce(this.#nonce), additionalData);
    const plaintext = cipher.decrypt(ciphertext);
    this.#nonce += 1n;
    return plaintext;
  }
}

class SymmetricState {
  #chainingKey: Uint8Array;
  #handshakeHash: Uint8Array;
  #cipher: CipherState | undefined;

  constructor(prologue: Uint8Array, responderStaticPublicKey: Uint8Array) {
    const protocolName = new TextEncoder().encode(NOISE_PROTOCOL_NAME);
    const initialHash =
      protocolName.length <= HASH_LENGTH
        ? concat(protocolName, new Uint8Array(HASH_LENGTH - protocolName.length))
        : sha256(protocolName);
    this.#chainingKey = initialHash;
    this.#handshakeHash = Uint8Array.from(initialHash);
    this.mixHash(prologue);
    this.mixHash(responderStaticPublicKey);
  }

  get handshakeHash(): Uint8Array {
    return Uint8Array.from(this.#handshakeHash);
  }

  mixHash(data: Uint8Array): void {
    this.#handshakeHash = sha256(concat(this.#handshakeHash, data));
  }

  mixKey(inputKeyMaterial: Uint8Array): void {
    const [chainingKey, cipherKey] = hkdf2(this.#chainingKey, inputKeyMaterial);
    this.#chainingKey = chainingKey;
    this.#cipher = new CipherState(cipherKey);
  }

  encryptAndHash(plaintext: Uint8Array): Uint8Array {
    const ciphertext =
      this.#cipher === undefined
        ? Uint8Array.from(plaintext)
        : this.#cipher.encryptWithAd(this.#handshakeHash, plaintext);
    this.mixHash(ciphertext);
    return ciphertext;
  }

  decryptAndHash(ciphertext: Uint8Array): Uint8Array {
    const plaintext =
      this.#cipher === undefined
        ? Uint8Array.from(ciphertext)
        : this.#cipher.decryptWithAd(this.#handshakeHash, ciphertext);
    this.mixHash(ciphertext);
    return plaintext;
  }

  split(): [CipherState, CipherState] {
    const [firstKey, secondKey] = hkdf2(this.#chainingKey, emptyBytes);
    return [new CipherState(firstKey), new CipherState(secondKey)];
  }
}

class NoiseIkInitiatorState implements NoiseIkInitiator {
  readonly #staticPrivateKey: Uint8Array;
  readonly #ephemeralPrivateKey: Uint8Array;
  readonly #responderStaticPublicKey: Uint8Array;
  readonly #symmetric: SymmetricState;
  #firstMessageWritten = false;
  #handshakeComplete = false;
  #sendCipher: CipherState | undefined;
  #receiveCipher: CipherState | undefined;

  constructor(options: NoiseIkInitiatorOptions) {
    this.#staticPrivateKey = copyExact(
      options.staticPrivateKey,
      X25519_KEY_LENGTH,
      "staticPrivateKey",
    );
    this.#ephemeralPrivateKey = copyExact(
      options.ephemeralPrivateKey,
      X25519_KEY_LENGTH,
      "ephemeralPrivateKey",
    );
    this.#responderStaticPublicKey = copyExact(
      options.responderStaticPublicKey,
      X25519_KEY_LENGTH,
      "responderStaticPublicKey",
    );
    const prologue = copyBytes(options.prologue, "prologue");
    this.#symmetric = new SymmetricState(prologue, this.#responderStaticPublicKey);
  }

  get handshakeHash(): Uint8Array {
    if (!this.#handshakeComplete) {
      throw new Error("Noise IK handshake is not complete");
    }
    return this.#symmetric.handshakeHash;
  }

  writeHandshakeMessage(payloadValue: Uint8Array): Uint8Array {
    if (this.#firstMessageWritten) {
      throw new Error("Noise IK initiator handshake message was already written");
    }
    const payload = copyBytes(payloadValue, "payload");
    const ephemeralPublicKey = x25519.getPublicKey(this.#ephemeralPrivateKey);
    this.#symmetric.mixHash(ephemeralPublicKey);
    this.#symmetric.mixKey(
      x25519.getSharedSecret(this.#ephemeralPrivateKey, this.#responderStaticPublicKey),
    );
    const staticPublicKey = x25519.getPublicKey(this.#staticPrivateKey);
    const encryptedStaticKey = this.#symmetric.encryptAndHash(staticPublicKey);
    this.#symmetric.mixKey(
      x25519.getSharedSecret(this.#staticPrivateKey, this.#responderStaticPublicKey),
    );
    const encryptedPayload = this.#symmetric.encryptAndHash(payload);
    this.#firstMessageWritten = true;
    return concat(ephemeralPublicKey, encryptedStaticKey, encryptedPayload);
  }

  readHandshakeMessage(messageValue: Uint8Array): Uint8Array {
    if (!this.#firstMessageWritten || this.#handshakeComplete) {
      throw new Error("Noise IK initiator is not ready for the responder message");
    }
    const message = copyBytes(messageValue, "message");
    if (message.length < X25519_KEY_LENGTH + CHACHA_TAG_LENGTH) {
      throw new Error("Noise IK responder message is truncated");
    }
    const responderEphemeralPublicKey = message.subarray(0, X25519_KEY_LENGTH);
    this.#symmetric.mixHash(responderEphemeralPublicKey);
    this.#symmetric.mixKey(
      x25519.getSharedSecret(this.#ephemeralPrivateKey, responderEphemeralPublicKey),
    );
    this.#symmetric.mixKey(
      x25519.getSharedSecret(this.#staticPrivateKey, responderEphemeralPublicKey),
    );
    const payload = this.#symmetric.decryptAndHash(message.subarray(X25519_KEY_LENGTH));
    [this.#sendCipher, this.#receiveCipher] = this.#symmetric.split();
    this.#handshakeComplete = true;
    return payload;
  }

  encrypt(plaintextValue: Uint8Array): Uint8Array {
    if (!this.#handshakeComplete || this.#sendCipher === undefined) {
      throw new Error("Noise IK transport is not ready");
    }
    return this.#sendCipher.encryptWithAd(emptyBytes, copyBytes(plaintextValue, "plaintext"));
  }

  decrypt(ciphertextValue: Uint8Array): Uint8Array {
    if (!this.#handshakeComplete || this.#receiveCipher === undefined) {
      throw new Error("Noise IK transport is not ready");
    }
    return this.#receiveCipher.decryptWithAd(
      emptyBytes,
      copyBytes(ciphertextValue, "ciphertext"),
    );
  }
}

export function createNoiseIkInitiator(options: NoiseIkInitiatorOptions): NoiseIkInitiator {
  return new NoiseIkInitiatorState(options);
}

