async function refreshHostedAccessToken(): Promise<string> {
  const currentTimeSeconds = Math.floor(Date.now() / 1_000);
  if (
    activeHostedAccessToken !== undefined &&
    activeHostedAccessTokenExpiresAt !== undefined &&
    activeHostedAccessTokenExpiresAt > currentTimeSeconds + 30
  ) {
    return activeHostedAccessToken;
  }
  if (hostedAccessRefresh !== undefined) {
    return hostedAccessRefresh;
  }
  hostedAccessRefresh = (async () => {
    const account = await resumeDesktopAccount({
      apiBaseUrl: HOSTED_API_BASE_URL,
      fetch: fetchAdapter,
      credentialStore,
      currentTimeSeconds,
    });
    activeProfile = account.mode === "signed-out" ? undefined : account.profile;
    if (account.mode !== "online") {
      activeHostedAccessToken = undefined;
      activeHostedAccessTokenExpiresAt = undefined;
      throw new Error("Hosted account is offline");
    }
    activeHostedAccessToken = account.accessToken;
    activeHostedAccessTokenExpiresAt = account.accessTokenExpiresAt;
    return account.accessToken;
  })();
  try {
    return await hostedAccessRefresh;
  } finally {
    hostedAccessRefresh = undefined;
  }
}

