function waitForOpen(socket: WebSocket): Promise<void> {
  if (socket.readyState === WebSocket.OPEN) {
    return Promise.resolve();
  }
  return new Promise((resolve, reject) => {
    const timeout = window.setTimeout(() => reject(new Error("Runner relay open timed out")), SOCKET_TIMEOUT_MS);
    socket.addEventListener(
      "open",
      () => {
        window.clearTimeout(timeout);
        resolve();
      },
      { once: true },
    );
    socket.addEventListener(
      "error",
      () => {
        window.clearTimeout(timeout);
        reject(new Error("Runner relay could not be opened"));
      },
      { once: true },
    );
  });
}

function receiveMessage(socket: WebSocket): Promise<string | ArrayBuffer> {
  return new Promise((resolve, reject) => {
    const timeout = window.setTimeout(() => reject(new Error("Runner relay response timed out")), SOCKET_TIMEOUT_MS);
    socket.addEventListener(
      "message",
      (event) => {
        window.clearTimeout(timeout);
        if (typeof event.data === "string" || event.data instanceof ArrayBuffer) {
          resolve(event.data);
          return;
        }
        reject(new Error("Runner relay returned an unsupported frame"));
      },
      { once: true },
    );
    socket.addEventListener(
      "close",
      () => {
        window.clearTimeout(timeout);
        reject(new Error("Runner relay closed before responding"));
      },
      { once: true },
    );
  });
}

