function RunnerRepositoryPanel({
  repositories,
  loading,
  importing,
  repositoryName,
  repositoryUrl,
  onLoad,
  onNameChange,
  onUrlChange,
  onImport,
}: {
  repositories: Repo[] | null;
  loading: boolean;
  importing: boolean;
  repositoryName: string;
  repositoryUrl: string;
  onLoad: () => void;
  onNameChange: (value: string) => void;
  onUrlChange: (value: string) => void;
  onImport: () => void;
}) {
  return (
    <div className="mt-5 rounded-lg border border-gray-700 bg-gray-950/70 p-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h3 className="text-sm font-semibold text-gray-100">BYOC repositories</h3>
          <p className="mt-1 text-sm text-gray-400">
            Repository commands and responses stay inside the encrypted runner channel.
          </p>
        </div>
        <button
          type="button"
          onClick={onLoad}
          disabled={loading}
          className="rounded border border-gray-700 px-3 py-2 text-sm text-gray-200 hover:border-gray-500 disabled:opacity-50"
        >
          {loading ? "Loading..." : "Load BYOC repositories"}
        </button>
      </div>

      {repositories !== null ? (
        <div className="mt-4 space-y-2">
          {repositories.length === 0 ? (
            <p className="text-sm text-gray-500">No repositories on this runner.</p>
          ) : (
            repositories.map((repository) => (
              <div
                key={repository.id}
                className="flex items-center justify-between rounded border border-gray-800 bg-gray-900 px-3 py-2"
              >
                <span className="text-sm font-medium text-gray-200">{repository.name}</span>
                <span className="rounded border border-gray-700 px-2 py-0.5 text-[11px] font-medium uppercase tracking-wide text-gray-400">
                  BYOC
                </span>
              </div>
            ))
          )}
        </div>
      ) : null}

      <div className="mt-4 grid gap-3 border-t border-gray-800 pt-4 md:grid-cols-[minmax(0,0.7fr)_minmax(0,1.3fr)_auto] md:items-end">
        <label className="block text-sm text-gray-300">
          Repository name
          <input
            aria-label="Repository name"
            value={repositoryName}
            onChange={(event) => onNameChange(event.target.value)}
            className="input mt-1 w-full"
            placeholder="project"
            autoComplete="off"
          />
        </label>
        <label className="block text-sm text-gray-300">
          Repository HTTPS URL
          <input
            aria-label="Repository HTTPS URL"
            value={repositoryUrl}
            onChange={(event) => onUrlChange(event.target.value)}
            className="input mt-1 w-full"
            placeholder="https://example.com/team/project.git"
            autoComplete="off"
          />
        </label>
        <button
          type="button"
          onClick={onImport}
          disabled={importing || !repositoryName.trim() || !repositoryUrl.trim()}
          className="btn-primary px-3 py-2 text-sm disabled:opacity-50"
        >
          {importing ? "Importing..." : "Import to BYOC"}
        </button>
      </div>
    </div>
  );
}

