            "Authorization": f"Bearer {self._principal.bearer_token}",
            "X-Requested-With": "XMLHttpRequest",
        }
        async with httpx.AsyncClient(
            transport=transport,
            base_url="http://localhost",
            headers=headers,
            follow_redirects=False,
            timeout=httpx.Timeout(30.0),
        ) as client:
