import { describe, expect, it, vi } from "vitest";

import { createRuntimeTransport } from "./runtimeTransport";

const runnerPublicKey = "REDACTED";

function apiClient() {
  return {
    get: vi.fn(),
    post: vi.fn(),
    patch: vi.fn(),
    put: vi.fn(),
    delete: vi.fn(),
  };
}

describe("runtime transport", () => {
  it("keeps local and hosted JSON calls on their selected gateway", async () => {
    const client = apiClient();
    client.get.mockResolvedValue([{ id: "repo-1" }]);
    const encryptedRequest = vi.fn();
    const transport = createRuntimeTransport(
      { location: "local" },
      { apiClient: client, encryptedRequest },
    );

    await expect(transport.get("/api/repos")).resolves.toEqual([{ id: "repo-1" }]);
    expect(client.get).toHaveBeenCalledWith("/api/repos");
    expect(encryptedRequest).not.toHaveBeenCalled();
  });

  it("maps BYOC JSON routes to least-privilege encrypted capabilities", async () => {
    const client = apiClient();
    const encryptedRequest = vi.fn().mockResolvedValue([]);
    const transport = createRuntimeTransport(
      { location: "byoc", runnerId: "runner-1", runnerPublicKey },
      { apiClient: client, encryptedRequest },
    );

    await expect(transport.get("/api/repos")).resolves.toEqual([]);
    expect(encryptedRequest).toHaveBeenCalledWith({
      expectedRunnerPublicKey: runnerPublicKey,
      scopes: ["repository.read"],
      method: "GET",
      path: "/api/repos",
      body: null,
      maxSessionBytes: 262_144,
    });
    expect(client.get).not.toHaveBeenCalled();
  });

  it("rejects control-plane and malformed BYOC routes before issuing a capability", async () => {
    const encryptedRequest = vi.fn();
    const transport = createRuntimeTransport(
      { location: "byoc", runnerId: "runner-1", runnerPublicKey },
      { apiClient: apiClient(), encryptedRequest },
    );

    await expect(transport.get("/api/settings/runner")).rejects.toThrow(
      "not allowed",
    );
    await expect(
      transport.get("/api/repos/../../control"),
    ).rejects.toThrow("not allowed");
    expect(encryptedRequest).not.toHaveBeenCalled();
  });

  it("separates workspace and session read and write scopes", async () => {
    const encryptedRequest = vi.fn().mockResolvedValue({});
    const transport = createRuntimeTransport(
      { location: "byoc", runnerId: "runner-1", runnerPublicKey },
      { apiClient: apiClient(), encryptedRequest },
    );
    const resourceId = "a".repeat(32);

    await transport.post(`/api/repos/${resourceId}/workspaces`, { name: "feature" });
    await transport.get(`/api/sessions/${resourceId}/messages`);

    expect(encryptedRequest).toHaveBeenNthCalledWith(1, {
      expectedRunnerPublicKey: runnerPublicKey,
      scopes: ["workspace.write"],
      method: "POST",
      path: `/api/repos/${resourceId}/workspaces`,
      body: { name: "feature" },
      maxSessionBytes: 262_144,
    });
    expect(encryptedRequest).toHaveBeenNthCalledWith(2, {
      expectedRunnerPublicKey: runnerPublicKey,
      scopes: ["session.read"],
      method: "GET",
      path: `/api/sessions/${resourceId}/messages`,
      body: null,
      maxSessionBytes: 262_144,
    });
  });
});

import { api } from "../api/client";
import {
  requestEncryptedRunner,
  type EncryptedRunnerRequest,
} from "../runner/encryptedRunnerClient";

export type RuntimeRef =
  | { readonly location: "local" }
  | { readonly location: "hosted" }
  | {
      readonly location: "byoc";
      readonly runnerId: string;
      readonly runnerPublicKey: string;
    };

type RuntimeMethod = "DELETE" | "GET" | "PATCH" | "POST" | "PUT";

interface JsonApiClient {
  get<T>(path: string): Promise<T>;
  post<T>(path: string, body?: unknown): Promise<T>;
  patch<T>(path: string, body?: unknown): Promise<T>;
  put<T>(path: string, body?: unknown): Promise<T>;
  delete(path: string): Promise<void>;
}

type EncryptedRequest = <T>(request: EncryptedRunnerRequest) => Promise<T>;

interface RuntimeTransportDependencies {
  readonly apiClient: JsonApiClient;
  readonly encryptedRequest: EncryptedRequest;
}

export interface RuntimeTransport {
  readonly runtime: RuntimeRef;
  get<T>(path: string): Promise<T>;
  post<T>(path: string, body?: unknown): Promise<T>;
  patch<T>(path: string, body?: unknown): Promise<T>;
  put<T>(path: string, body?: unknown): Promise<T>;
  delete(path: string): Promise<void>;
}

const defaultDependencies: RuntimeTransportDependencies = {
  apiClient: api,
  encryptedRequest: requestEncryptedRunner,
};

const RESOURCE_ID = "[0-9a-f]{32}";
const REPOSITORY_MEMBER_PATH = new RegExp(`^/api/repos/${RESOURCE_ID}$`);
const WORKSPACE_COLLECTION_PATH = new RegExp(
  `^/api/repos/${RESOURCE_ID}/workspaces$`,
);
const WORKSPACE_MEMBER_PATH = new RegExp(`^/api/workspaces/${RESOURCE_ID}$`);
const SESSION_COLLECTION_PATH = new RegExp(
  `^/api/workspaces/${RESOURCE_ID}/sessions$`,
);
const SESSION_MEMBER_PATH = new RegExp(`^/api/sessions/${RESOURCE_ID}$`);
const SESSION_READ_PATH = new RegExp(
  `^/api/sessions/${RESOURCE_ID}/(?:messages|tree)$`,
);
const BYOC_SESSION_BYTES = 262_144;

function requiredScope(method: RuntimeMethod, path: string): string {
  const repositoryCollection = path === "/api/repos";
  const repositoryMember = REPOSITORY_MEMBER_PATH.test(path);
  if (method === "GET" && (repositoryCollection || repositoryMember)) {
    return "repository.read";
  }
  if (
    (method === "POST" || method === "PATCH" || method === "DELETE") &&
    (repositoryCollection || repositoryMember)
  ) {
    return "repository.write";
  }

  const workspaceCollection = WORKSPACE_COLLECTION_PATH.test(path);
  const workspaceMember = WORKSPACE_MEMBER_PATH.test(path);
  if (method === "GET" && workspaceCollection) {
    return "workspace.read";
  }
  if (method === "POST" && workspaceCollection) {
    return "workspace.write";
  }
  if ((method === "PATCH" || method === "DELETE") && workspaceMember) {
    return "workspace.write";
  }

  const sessionCollection = SESSION_COLLECTION_PATH.test(path);
  const sessionMember = SESSION_MEMBER_PATH.test(path);
  const sessionRead = SESSION_READ_PATH.test(path);
  if (method === "GET" && (sessionCollection || sessionMember || sessionRead)) {
    return "session.read";
  }
  if (method === "POST" && sessionCollection) {
    return "session.write";
  }
  if (method === "PATCH" && sessionMember) {
    return "session.write";
  }
  throw new Error("BYOC runtime method or path is not allowed");
}

function validateRuntime(runtime: RuntimeRef): void {
  if (runtime.location === "local" || runtime.location === "hosted") {
    return;
  }
  if (!runtime.runnerId || runtime.runnerId.length > 256) {
    throw new Error("BYOC runner ID is invalid");
  }
  if (!runtime.runnerPublicKey) {
    throw new Error("BYOC runner public key is required");
  }
}

export function createRuntimeTransport(
  runtime: RuntimeRef,
  dependencies: RuntimeTransportDependencies = defaultDependencies,
): RuntimeTransport {
  validateRuntime(runtime);
  if (!dependencies.apiClient || typeof dependencies.apiClient.get !== "function") {
    throw new TypeError("Runtime API client is invalid");
  }
  if (typeof dependencies.encryptedRequest !== "function") {
    throw new TypeError("Encrypted runtime request must be callable");
  }

  async function request<T>(
    method: RuntimeMethod,
    path: string,
    body?: unknown,
  ): Promise<T> {
    if (runtime.location === "byoc") {
      const scope = requiredScope(method, path);
      return dependencies.encryptedRequest<T>({
        expectedRunnerPublicKey: runtime.runnerPublicKey,
        scopes: [scope],
        method,
        path,
        body: body ?? null,
        maxSessionBytes: BYOC_SESSION_BYTES,
      });
    }
    if (method === "GET") {
      return dependencies.apiClient.get<T>(path);
    }
    if (method === "POST") {
      return dependencies.apiClient.post<T>(path, body);
    }
    if (method === "PATCH") {
      return dependencies.apiClient.patch<T>(path, body);
    }
    if (method === "PUT") {
      return dependencies.apiClient.put<T>(path, body);
    }
    await dependencies.apiClient.delete(path);
    return undefined as T;
  }

  return {
    runtime,
    get: <T>(path: string) => request<T>("GET", path),
    post: <T>(path: string, body?: unknown) => request<T>("POST", path, body),
    patch: <T>(path: string, body?: unknown) => request<T>("PATCH", path, body),
    put: <T>(path: string, body?: unknown) => request<T>("PUT", path, body),
    delete: (path: string) => request<void>("DELETE", path),
  };
}

