import { beforeEach, describe, expect, it, vi } from "vitest";

const { mockConnect, mockConnection } = vi.hoisted(() => ({
  mockConnect: vi.fn(),
  mockConnection: {
    request: vi.fn(),
    close: vi.fn(),
  },
}));

vi.mock("../runner/encryptedRunnerClient", () => ({
  connectEncryptedRunner: mockConnect,
  RunnerRpcError: class RunnerRpcError extends Error {},
}));

import { uploadEncryptedPiConfig } from "./encryptedUpload";

const runtime = {
  location: "byoc" as const,
  runnerId: "runner-1",
  runnerPublicKey: "REDACTED",
};
const uploadId = "a".repeat(32);

describe("encrypted runtime upload", () => {
  beforeEach(() => {
    mockConnect.mockReset();
    mockConnection.request.mockReset();
    mockConnection.close.mockReset();
    mockConnect.mockResolvedValue(mockConnection);
  });

  it("streams ordered chunks through one capability-bound Noise session", async () => {
    const payload = new Uint8Array(30_000).fill(7);
    const file = new File([payload], "config.zip", { type: "application/zip" });
    mockConnection.request
      .mockResolvedValueOnce({
        id: uploadId,
        purpose: "pi_config",
        filename: "config.zip",
        size_bytes: payload.length,
        next_chunk_index: 0,
      })
      .mockResolvedValueOnce({
        id: uploadId,
        purpose: "pi_config",
        filename: "config.zip",
        size_bytes: payload.length,
        next_chunk_index: 1,
      })
      .mockResolvedValueOnce({
        id: uploadId,
        purpose: "pi_config",
        filename: "config.zip",
        size_bytes: payload.length,
        next_chunk_index: 2,
      })
      .mockResolvedValueOnce({ status: "ready" });

    await expect(uploadEncryptedPiConfig(runtime, file)).resolves.toEqual({
      status: "ready",
    });

    expect(mockConnect).toHaveBeenCalledWith({
      expectedRunnerPublicKey: runtime.runnerPublicKey,
      scopes: ["pi.configure"],
      maxSessionBytes: 134_217_728,
    });
    expect(mockConnection.request).toHaveBeenCalledTimes(4);
    expect(mockConnection.request).toHaveBeenLastCalledWith({
      method: "POST",
      path: `/api/settings/pi-config/uploads/${uploadId}/complete`,
    });
    expect(mockConnection.close).toHaveBeenCalledTimes(1);
  });

  it("rejects oversized files before issuing a capability", async () => {
    const file = { name: "large.zip", size: 50 * 1024 * 1024 + 1 } as File;

    await expect(uploadEncryptedPiConfig(runtime, file)).rejects.toThrow("50MB");
    expect(mockConnect).not.toHaveBeenCalled();
  });
});

import {
  connectEncryptedRunner,
  RunnerRpcError,
  type EncryptedRunnerConnection,
  type EncryptedRunnerOperation,
} from "../runner/encryptedRunnerClient";
import type { RuntimeRef } from "./runtimeTransport";

const FILE_BYTES_MAX = 50 * 1024 * 1024;
const CHUNK_BYTES = 24_000;
const SESSION_BYTES = 128 * 1024 * 1024;
const RESOURCE_ID_PATTERN = /^[0-9a-f]{32}$/;

interface UploadProgress {
  readonly id: string;
  readonly purpose: "pi_config";
  readonly filename: string;
  readonly size_bytes: number;
  readonly next_chunk_index: number;
}

function base64url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/gu, "-").replace(/\//gu, "_").replace(/=+$/u, "");
}

function hex(bytes: Uint8Array): string {
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function validateProgress(
  value: unknown,
  expected: {
    readonly id?: string;
    readonly filename: string;
    readonly sizeBytes: number;
    readonly nextChunkIndex: number;
  },
): UploadProgress {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Encrypted upload response is invalid");
  }
  const progress = value as Record<string, unknown>;
  if (
    Object.keys(progress).length !== 5 ||
    typeof progress.id !== "string" ||
    !RESOURCE_ID_PATTERN.test(progress.id) ||
    (expected.id !== undefined && progress.id !== expected.id) ||
    progress.purpose !== "pi_config" ||
    progress.filename !== expected.filename ||
    progress.size_bytes !== expected.sizeBytes ||
    progress.next_chunk_index !== expected.nextChunkIndex
  ) {
    throw new Error("Encrypted upload response did not match the transfer");
  }
  return progress as unknown as UploadProgress;
}

function validateFile(file: File): void {
  if (!file || typeof file.name !== "string" || typeof file.size !== "number") {
    throw new TypeError("Pi config upload must be a file");
  }
  if (
    !file.name ||
    file.name.length > 255 ||
    file.name !== file.name.trim() ||
    file.name.includes("/") ||
    file.name.includes("\\") ||
    !file.name.toLowerCase().endsWith(".zip")
  ) {
    throw new Error("Pi config upload must have a simple .zip filename");
  }
  if (!Number.isSafeInteger(file.size) || file.size < 1 || file.size > FILE_BYTES_MAX) {
    throw new Error("Pi config upload must be between 1 byte and 50MB");
  }
}

export async function uploadEncryptedPiConfig<T>(
  runtime: Extract<RuntimeRef, { location: "byoc" }>,
  file: File,
): Promise<T> {
  if (runtime.location !== "byoc" || !runtime.runnerPublicKey) {
    throw new Error("Encrypted upload requires a paired BYOC runtime");
  }
  validateFile(file);
  const fileBytes = new Uint8Array(await file.arrayBuffer());
  if (fileBytes.length !== file.size) {
    fileBytes.fill(0);
    throw new Error("Pi config file size changed while reading");
  }
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", fileBytes));
  let connection: EncryptedRunnerConnection | null = null;
  let uploadId: string | null = null;

  const connect = async (): Promise<EncryptedRunnerConnection> =>
    connectEncryptedRunner({
      expectedRunnerPublicKey: runtime.runnerPublicKey,
      scopes: ["pi.configure"],
      maxSessionBytes: SESSION_BYTES,
    });
  const invoke = async <Result>(operation: EncryptedRunnerOperation): Promise<Result> => {
    for (let attempt = 0; attempt < 5; attempt += 1) {
      connection ??= await connect();
      try {
        return await connection.request<Result>(operation);
      } catch (error) {
        if (error instanceof RunnerRpcError) throw error;
        connection.close();
        connection = null;
        if (attempt === 4) throw error;
      }
    }
    throw new Error("Encrypted upload retry limit reached");
  };

  try {
    const started = validateProgress(
      await invoke({
        method: "POST",
        path: "/api/settings/pi-config/uploads",
        body: {
          purpose: "pi_config",
          filename: file.name,
          size_bytes: fileBytes.length,
          sha256: hex(digest),
        },
      }),
      {
        filename: file.name,
        sizeBytes: fileBytes.length,
        nextChunkIndex: 0,
      },
    );
    uploadId = started.id;
    const chunkCount = Math.ceil(fileBytes.length / CHUNK_BYTES);
    for (let chunkIndex = 0; chunkIndex < chunkCount; chunkIndex += 1) {
      const offset = chunkIndex * CHUNK_BYTES;
      const chunk = fileBytes.subarray(offset, Math.min(offset + CHUNK_BYTES, fileBytes.length));
      validateProgress(
        await invoke({
          method: "POST",
          path: `/api/settings/pi-config/uploads/${uploadId}/chunks/${chunkIndex}`,
          body: { data: base64url(chunk) },
        }),
        {
          id: uploadId,
          filename: file.name,
          sizeBytes: fileBytes.length,
          nextChunkIndex: chunkIndex + 1,
        },
      );
    }
    return await invoke<T>({
      method: "POST",
      path: `/api/settings/pi-config/uploads/${uploadId}/complete`,
    });
  } catch (error) {
    if (uploadId && connection) {
      try {
        await connection.request({
          method: "DELETE",
          path: `/api/settings/pi-config/uploads/${uploadId}`,
        });
      } catch {
        // Incomplete uploads expire from runner memory after a bounded interval.
      }
    }
    throw error;
  } finally {
    digest.fill(0);
    fileBytes.fill(0);
    connection?.close();
  }
}

