      const buildResultMessage = (resultUsage) => ({
        id: sessionId,
        type: "message",
        data: {
          type: "result",
          usage: resultUsage || {},
          provider: model.provider,
          model: `${model.provider}/${model.id}`,
        },
      });

      clearFinalizeTimer = () => {
        if (finalizeTimer) {
          clearTimeout(finalizeTimer);
          finalizeTimer = null;
        }
      };

      const schedulePendingResult = () => {
        clearFinalizeTimer();
        finalizeTimer = setTimeout(() => {
          finalizeTimer = null;
          if (resultSent || compactionActive || !pendingResult) {
            return;
          }
          sendToSocket(socket, pendingResult);
          pendingResult = null;
          resultSent = true;
        }, 0);
      };

      entry.unsubscribe = piSession.subscribe((event) => {
        // Temporary diagnostic so we can see every event pi emits while we
        // track down why turns never reach the browser.
        console.log(`[sidecar][event] session=${sessionId} type=${event.type}`);
        switch (event.type) {
          case "message_update": {
            const assistantEvent = event.assistantMessageEvent;
            if (assistantEvent.type === "text_delta") {
              sendToSocket(socket, {
                id: sessionId,
                type: "message",
                data: {
                  type: "assistant",
                  message: {
                    content: [{ type: "text", text: assistantEvent.delta }],
                  },
                },
              });
            } else if (assistantEvent.type === "thinking_delta") {
              sendToSocket(socket, {
                id: sessionId,
                type: "message",
                data: {
                  type: "assistant",
                  message: {
                    content: [
                      { type: "thinking", thinking: assistantEvent.delta },
                    ],
                  },
                },
              });
            }
            break;
          }
          case "tool_execution_start":
            sendToSocket(socket, {
              id: sessionId,
              type: "message",
              data: {
                type: "tool_use",
                id: event.toolCallId,
                toolName: event.toolName,
                toolInput: event.args,
              },
            });
            break;
          case "tool_execution_update":
            sendToSocket(socket, {
              id: sessionId,
              type: "tool_result",
              tool_use_id: event.toolCallId,
              content: stringifyToolResult(event.partialResult),
              partial: true,
            });
            break;
          case "tool_execution_end":
            sendToSocket(socket, {
              id: sessionId,
              type: "tool_result",
              tool_use_id: event.toolCallId,
              content: stringifyToolResult(event.result),
              is_error: event.isError === true,
            });
            break;
          case "turn_end":
            if (event.message && event.message.usage) {
              const eventUsage = event.message.usage;
              usage = {
                input_tokens: eventUsage.input || 0,
                output_tokens: eventUsage.output || 0,
                cache_read_input_tokens: eventUsage.cacheRead || 0,
                cache_creation_input_tokens: eventUsage.cacheWrite || 0,
              };
            }
            break;
          case "agent_end":
            pendingResult = buildResultMessage(usage);
            usage = null;
            agentEndEmitted = true;
            schedulePendingResult();
            break;
          case "auto_retry_start":
            pendingResult = null;
            clearFinalizeTimer();
            console.log(
              `[sidecar] Retrying provider request (attempt ${event.attempt}/${event.maxAttempts})`,
            );
            sendStatusToSocket(
              socket,
              sessionId,
              "retrying",
              `Retrying after provider error (attempt ${event.attempt}/${event.maxAttempts})...`,
            );
            break;
          case "auto_retry_end":
            sendStatusToSocket(
              socket,
              sessionId,
              event.success ? "retry_complete" : "retry_failed",
              event.success ? "Retry complete." : "Retry failed.",
              event.success ? "info" : "warning",
            );
            break;
          case "compaction_start":
            compactionActive = true;
            clearFinalizeTimer();
            console.log("[sidecar] Compacting context...");
            sendStatusToSocket(
              socket,
              sessionId,
              "compacting",
              "Compacting context...",
              "info",
              { reason: event.reason },
            );
            break;
          case "compaction_end":
            compactionActive = false;
            if (event.willRetry) {
              pendingResult = null;
            }
            sendStatusToSocket(
              socket,
              sessionId,
              event.errorMessage ? "compaction_failed" : "compacted",
              event.errorMessage || "Context compacted.",
              event.errorMessage ? "warning" : "info",
              {
                reason: event.reason,
                willRetry: event.willRetry === true,
                aborted: event.aborted === true,
              },
            );
            if (!event.willRetry) {
              schedulePendingResult();
            }
            break;
        }
      });

      console.log(`[sidecar] piSession.prompt start session=${sessionId}`);
      await piSession.prompt(prompt);
      console.log(`[sidecar] piSession.prompt end session=${sessionId}`);
      // Clear cancelRequested after normal completion
      entry.cancelRequested = false;

      // Pi returns from prompt() without firing agent_end when it handles an
      // extension command inline (e.g. `/rtk-stats`). Synthesise the result
      // event so the client stream loop terminates cleanly instead of hanging.
      if (!agentEndEmitted && !resultSent) {
        console.log(`[sidecar] synthesising result for session ${sessionId}`);
        sendToSocket(socket, buildResultMessage(usage));
        resultSent = true;
      }
    } catch (err) {
      clearFinalizeTimer();
      const errorMessage = err instanceof Error ? err.message : String(err);
      if (entry?.cancelRequested) {
        console.log(`[sidecar] Session ${sessionId} cancelled by user`);
        sendToSocket(socket, {
          id: sessionId,
          type: "cancelled",
        });
        // Clear cancelRequested after handling cancellation
        entry.cancelRequested = false;
      } else {
        console.error(`[sidecar] Session ${sessionId} failed`);
        sendToSocket(socket, {
          id: sessionId,
          type: "error",
          error: errorMessage,
        });
      }
    }
  }

  async cancelSession(sessionId) {
    const entry = this.activeSessions.get(sessionId);
    if (!entry) {
      console.log(`[sidecar] Session ${sessionId} not found`);
      return;
    }
    console.log(`[sidecar] Cancelling session ${sessionId}`);
    entry.cancelRequested = true;
    entry.piSession.abortCompaction();
    entry.piSession.abortRetry();
    await entry.piSession.abort();
  }

  cleanup() {
    try {
      if (fs.existsSync(this.socketPath)) {
        fs.unlinkSync(this.socketPath);
      }
    } catch {
      // ignore cleanup races
    }

