      return {
        ready: { port: 43123, instanceNonce: "a".repeat(43) },
        processId: 123,
        running: true,
        stop: async () => {
          stopped = true;
          events.push("helper:stop");
        },
      };
    },
    bootstrapHelper: async () => {
      events.push("helper:bootstrap");
