import WorkspaceInspector from "../WorkspaceInspector";

class FakeWebSocket extends EventTarget {
  static readonly CONNECTING = 0;
  static readonly OPEN = 1;
  static readonly CLOSING = 2;
  static readonly CLOSED = 3;
  static instances: FakeWebSocket[] = [];

  readyState = FakeWebSocket.CONNECTING;
  readonly sentMessages: string[] = [];
  readonly url: string;

  constructor(url: string | URL) {
    super();
    this.url = String(url);
    FakeWebSocket.instances.push(this);
  }

  send(message: string): void {
    this.sentMessages.push(message);
  }

  close(): void {
    this.readyState = FakeWebSocket.CLOSED;
  }

  closeFromServer(code = 1006): void {
    this.readyState = FakeWebSocket.CLOSED;
    const event = new Event("close") as Event & { code: number };
    Object.defineProperty(event, "code", { value: code });
    this.dispatchEvent(event);
  }
}

class FakeResizeObserver {
  observe(): void {
    return undefined;
  }

  disconnect(): void {
    return undefined;
  }
}

async function waitForWebSocketCount(count: number): Promise<void> {
  await waitFor(() => {
    expect(FakeWebSocket.instances).toHaveLength(count);
  });
}

function setTerminalThemeVariables(background: string, foreground: string): void {
  const rootStyle = document.documentElement.style;
  rootStyle.setProperty("--gray-900", background);
  rootStyle.setProperty("--gray-200", foreground);
  rootStyle.setProperty("--gray-50", foreground);
  rootStyle.setProperty("--gray-600", foreground);
  rootStyle.setProperty("--gray-400", foreground);
}

describe("WorkspaceInspector terminal", () => {
  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
    document.documentElement.classList.remove("dark");
    document.documentElement.removeAttribute("style");
  });

  beforeEach(() => {
    vi.clearAllMocks();
    FakeWebSocket.instances = [];
    terminalInstances.length = 0;
    apiGetMock.mockResolvedValue({ files: [] });
    setTerminalThemeVariables("240 230 211", "45 37 32");
    vi.stubGlobal("WebSocket", FakeWebSocket);
    vi.stubGlobal("ResizeObserver", FakeResizeObserver);
  });

  it("reconnects when Restart is clicked after the terminal socket closes", async () => {
    render(
      <WorkspaceInspector
        workspaceId={WORKSPACE_ID}
        transport={runtimeTransport}
        refreshKey={0}
      />,
    );

    await waitForWebSocketCount(1);

    act(() => {
      FakeWebSocket.instances[0].closeFromServer();
    });

    expect(screen.getByText("Disconnected. Retrying...")).toBeInTheDocument();
    fireEvent.click(screen.getByRole("button", { name: "Restart" }));

    await waitForWebSocketCount(2);
    expect(terminalResetMock).toHaveBeenCalled();
    expect(FakeWebSocket.instances[1].url).toBe(WORKSPACE_TERMINAL_URL);
    expect(screen.getByText("Connecting...")).toBeInTheDocument();
  });

  it("updates terminal colors when the document theme changes", async () => {
    render(
      <WorkspaceInspector
        workspaceId={WORKSPACE_ID}
        transport={runtimeTransport}
        refreshKey={0}
      />,
    );

    await waitForWebSocketCount(1);
    expect(terminalInstances[0].options.theme).toMatchObject({
      background: LIGHT_TERMINAL_BACKGROUND,
      foreground: LIGHT_TERMINAL_FOREGROUND,
      cursor: TERMINAL_CURSOR,
    });

    setTerminalThemeVariables("26 20 16", "224 209 184");
    document.documentElement.classList.add("dark");

    await waitFor(() => {
      expect(terminalInstances[0].options.theme).toMatchObject({
        background: DARK_TERMINAL_BACKGROUND,
        foreground: DARK_TERMINAL_FOREGROUND,
        cursor: TERMINAL_CURSOR,
      });
    });
  });

  it("automatically retries when the terminal runtime is temporarily unavailable", async () => {
    render(
      <WorkspaceInspector
        workspaceId={WORKSPACE_ID}
        transport={runtimeTransport}
        refreshKey={0}
      />,
    );

    await waitForWebSocketCount(1);

    vi.useFakeTimers();
    try {
      act(() => {
        FakeWebSocket.instances[0].closeFromServer(TERMINAL_TEMPORARY_FAILURE_CLOSE_CODE);
      });

      expect(screen.getByText("Terminal unavailable. Retrying...")).toBeInTheDocument();
      await act(async () => {
        await vi.advanceTimersByTimeAsync(TERMINAL_RECONNECT_DELAY_MS);
      });

      expect(FakeWebSocket.instances).toHaveLength(2);
      expect(FakeWebSocket.instances[1].url).toBe(WORKSPACE_TERMINAL_URL);
    } finally {
      vi.useRealTimers();
    }
  });
});

  workspaceId,
  transport,
  active,
}: {
  workspaceId: string;
  transport: RuntimeTransport;
  active: boolean;
}) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const terminalRef = useRef<Terminal | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const channelRef = useRef<RuntimeTerminalChannel | null>(null);
  const [status, setStatus] = useState(active ? "Connecting..." : "Paused");
  const [connectionVersion, setConnectionVersion] = useState(0);

  const fit = useCallback(() => {
    const terminal = terminalRef.current;
    const fitAddon = fitRef.current;
    if (!terminal || !fitAddon) return;
    try {
      fitAddon.fit();
      const channel = channelRef.current;
      if (channel) {
        void channel.resize(terminal.cols, terminal.rows).catch(() => {
          setStatus("Terminal resize failed");
        });
      }
    } catch {
      // The terminal can be hidden during mobile drawer transitions.
    }
  }, []);

  useEffect(() => {
    if (!active) {
      setStatus("Paused");
      return;
    }
    const container = containerRef.current;
    if (!container) return;
    const abortController = new AbortController();
    let disposed = false;
    let reconnectTimer: number | null = null;
    setStatus("Connecting...");

    const terminal = new Terminal({
      cursorBlink: true,
      fontFamily: 'Menlo, Monaco, "Courier New", monospace',
      fontSize: 12,
      scrollback: 1000,
      theme: terminalTheme(),
    });
    const fitAddon = new FitAddon();
    terminal.loadAddon(fitAddon);
    terminal.open(container);
    terminalRef.current = terminal;
    fitRef.current = fitAddon;
    try {
      fitAddon.fit();
    } catch {
      // Initial layout can still be hidden while a drawer opens.
    }

    const inputSubscription = terminal.onData((data) => {
      const channel = channelRef.current;
      if (channel) {
        void channel.sendInput(data).catch(() => setStatus("Terminal input failed"));
      }
    });
    const observer = new ResizeObserver(() => fit());
    observer.observe(container);
    const themeObserver = new MutationObserver(() => {
      terminal.options.theme = terminalTheme();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    void (async () => {
      try {
        const channel = await openRuntimeTerminal(transport, workspaceId, {
          cols: terminal.cols,
          rows: terminal.rows,
          signal: abortController.signal,
        });
        if (disposed) {
          await channel.close();
          return;
        }
        channelRef.current = channel;
        setStatus("Connected");
        for await (const event of channel.events()) {
          if (event.type === "terminal_ready") {
            if (typeof event.replay === "string" && event.replay) {
              terminal.write(event.replay);
            }
            setStatus("Connected");
            fit();
          } else if (event.type === "terminal_data" && typeof event.data === "string") {
            terminal.write(event.data);
          } else if (event.type === "terminal_exit") {
            setStatus("Shell exited. Restart to open a new terminal.");
          } else if (event.type === "error") {
            setStatus(typeof event.error === "string" ? event.error : "Terminal error");
          }
        }
        if (!disposed) {
          setStatus("Disconnected. Retrying...");
          reconnectTimer = window.setTimeout(
            () => setConnectionVersion((value) => value + 1),
            TERMINAL_RECONNECT_DELAY_MS,
          );
        }
      } catch (error) {
        if (disposed || (error instanceof DOMException && error.name === "AbortError")) return;
        setStatus(error instanceof Error ? error.message : "Terminal connection failed");
        reconnectTimer = window.setTimeout(
          () => setConnectionVersion((value) => value + 1),
          TERMINAL_RECONNECT_DELAY_MS,
        );
      }
    })();

    return () => {
      disposed = true;
      abortController.abort();
      if (reconnectTimer !== null) window.clearTimeout(reconnectTimer);
      themeObserver.disconnect();
      observer.disconnect();
      inputSubscription.dispose();
      const channel = channelRef.current;
      channelRef.current = null;
      if (channel) void channel.close().catch(() => undefined);
      terminal.dispose();
      terminalRef.current = null;
      fitRef.current = null;
    };
  }, [active, connectionVersion, fit, transport, workspaceId]);

  const restart = useCallback(() => {
    terminalRef.current?.reset();
    const channel = channelRef.current;
    if (channel) {
      void channel.restart().catch(() => setStatus("Terminal restart failed"));
    } else {
      setConnectionVersion((value) => value + 1);
    }
  }, []);

  return (
    <div className="flex h-full min-h-0 flex-col bg-gray-900">
      <div className="flex items-center justify-between border-b border-gray-800 px-3 py-2">
        <div className="text-xs font-medium text-gray-300">Terminal</div>
        <div className="flex items-center gap-2">
          <span className="text-[11px] text-gray-500">{status}</span>
          <button
            type="button"
            onClick={restart}
            className="rounded px-2 py-1 text-[11px] text-gray-400 hover:bg-gray-800 hover:text-gray-100"
          >
            Restart
          </button>
        </div>
      </div>
      <div ref={containerRef} className="min-h-0 flex-1 overflow-hidden p-2" />
    </div>
  );
}

